import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { threeDs8InternalSchema, threeDs8Schema, type ThreeDs8 } from "./three-ds8.js";

export type Authentication = {
  /**
   * A unique identifier that is used to identify and reference an instance of this resource. It is
   * generated by Global Payments to identify the authentication details (3DS data) used with this
   * transaction.
   */
  id?: string;
  threeDs?: ThreeDs8;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const authenticationProperties: s.Shape<Authentication> = {
  id: s.optional(s.string()),
  threeDs: s.optional(s.lazy(() => threeDs8InternalSchema)),
  _keysMap: {
    threeDs: "three_ds",
  },
};

export const authenticationInternalSchema: Schema<Authentication> = s.object<Authentication>(
  authenticationProperties,
  { additionalProperties: s.json() },
);

export const authenticationSchema: Schema<Authentication> = s.lazySchema(() =>
  s.object<Authentication>(
    {
      ...authenticationProperties,
      id: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      threeDs: s.optional(s.lazy(() => threeDs8Schema)),
    },
    { additionalProperties: s.json() },
  ),
);
